async function startOnlineGame(){const col=cloud.collection(fbDb,'pacmanRooms',online.code,'players');online.playersUnsub?.();online.playersUnsub=cloud.onSnapshot(col,s=>{remotePlayers={};s.docs.forEach(d=>remotePlayers[d.id]={id:d.id,...d.data()})});config.pacCount=1;config.ghostCount=2;startGame(true)}
const canvas=$('#board'),ctx=canvas.getContext('2d');
function pass(tx,ty){return tx>=0&&tx<COLS&&ty>=0&&ty<ROWS&&MAP[ty][tx]!=='#'}
function initGame(isOnline=false){const pellets=MAP.map(r=>r.split('').map(c=>c==='.'||c==='o'?c:' '));let count=0;pellets.forEach(r=>r.forEach(c=>{if(c==='.'||c==='o')count++}));const pacs=[];for(let i=0;i<config.pacCount;i++)pacs.push({x:(1.5+(i%2)*2)*T,y:(1.5+Math.floor(i/2)*2)*T,dir:'right',want:'right',color:i===0?config.pacColor:palette[(i+1)%palette.length],bot:i>0,alive:true});const ghosts=[];for(let i=0;i<config.ghostCount;i++)ghosts.push({x:(8.5+(i%2))*T,y:(9.5+Math.floor(i/2))*T,dir:'left',want:'left',color:palette[(i+2)%palette.length],bot:isOnline?false:true,alive:true});game={pellets,pelletsLeft:count,pacs,ghosts,score:0,lives:3,power:0,over:false,won:false,tick:0,isOnline};$('#score').textContent='0';$('#remaining').textContent=count;$('#lives').textContent='3';$('#gameMessage').textContent=isOnline?`Sala ${online.code} · ${online.role==='pac'?'Você é Pac-Man':'Você é Fantasma'}`:'WASD / setas para mover';draw();}
function startGame(isOnline=false){$('#home').classList.add('hidden');$('#gameScreen').classList.add('active');$('#shareRoom').classList.toggle('hidden',!isOnline);$('#roomInfo').textContent=isOnline?`SALA ${online.code} · ${online.role==='pac'?'Pac-Man':'Fantasma'}`:'JOGO LOCAL';$('#playersList').innerHTML='';gameMode=isOnline?'online':'local';initGame(isOnline);last=performance.now();requestAnimationFrame(loop)}
