function syncOnlineActors(){if(!game?.isOnline)return;const previous=new Map([...game.pacs,...game.ghosts].map(e=>[e.uid,e]));const pacs=[],ghosts=[];for(const player of Object.values(remotePlayers)){const isPac=player.role==='pac',old=previous.get(player.id),entity=old||{x:Number(player.x)||T*1.5,y:Number(player.y)||T*1.5,dir:player.dir||'right',want:player.dir||'right',alive:true};entity.uid=player.id;entity.color=player.color||palette[0];entity.name=player.name||'Jogador';entity.bot=false;if(player.id!==localUser?.uid){entity.x=Number(player.x)||entity.x;entity.y=Number(player.y)||entity.y;entity.dir=player.dir||entity.dir} (isPac?pacs:ghosts).push(entity)}if(!pacs.length&&online.role==='pac')pacs.push({uid:localUser.uid,x:1.5*T,y:1.5*T,dir:'right',want:'right',color:config.pacColor,alive:true});if(!ghosts.length&&online.role==='ghost')ghosts.push({uid:localUser.uid,x:9.5*T,y:9.5*T,dir:'left',want:'left',color:palette[2],alive:true});game.pacs=pacs;game.ghosts=ghosts}
function update(dt){if(!game||game.over)return;game.tick+=dt;if(game.isOnline)syncOnlineActors();const myId=localUser?.uid;for(const p of game.pacs){if(game.isOnline){if(p.uid===myId&&online.role==='pac')move(p,dt,95,desiredDirFor(0));continue}if(p.bot){const near=game.ghosts[0]||{x:0,y:0};if(Math.random()<dt*2)chooseBot(p,{x:near.x,y:near.y},false);move(p,dt,80)}else move(p,dt,95,desiredDirFor(0))}
for(const g of game.ghosts){if(game.isOnline){if(g.uid===myId&&online.role==='ghost')move(g,dt,88,desiredDirFor(0));continue}if(g.bot){const target=game.pacs.filter(p=>p.alive).sort((a,b)=>Math.hypot(a.x-g.x,a.y-g.y)-Math.hypot(b.x-g.x,b.y-g.y))[0]||game.pacs[0];if(Math.random()<dt*2.7)chooseBot(g,{x:target.x,y:target.y},true);move(g,dt,game.power>0?60:76)}}
if(game.isOnline&&myId&&performance.now()-publishAt>180){publishAt=performance.now();const ent=online.role==='pac'?game.pacs.find(p=>p.uid===myId):game.ghosts.find(g=>g.uid===myId);if(ent)cloud.updateDoc(cloud.doc(fbDb,'pacmanRooms',online.code,'players',myId),{x:ent.x,y:ent.y,dir:ent.dir}).catch(()=>{})}

